using System;
using System.Diagnostics;
using System.Threading;
using System.IO;
using System.Globalization;

class ThreadStates {
    static int Main(string[] args) {
        int pid = int.Parse(args[0]), tid = int.Parse(args[1]);
        var target = Process.GetProcessById(pid);
        var jitter = new Random(5149);
        var start = DateTime.MaxValue;
        int initialCount = target.Threads.Count;
        foreach (ProcessThread t in target.Threads) {
            if (t.StartTime < start) { start = t.StartTime; tid = t.Id; }
        }
        // Bound both elapsed time and storage, never suspend the observed thread.
        int[] state = new int[2048], reason = new int[2048];
        long[] begin = new long[2048], end = new long[2048];
        var elapsed = Stopwatch.StartNew();
        int count = 0;
        while (count < state.Length && elapsed.ElapsedMilliseconds < 4750) {
            begin[count] = elapsed.ElapsedTicks;
            target.Refresh();
            bool found = false;
            foreach (ProcessThread t in target.Threads) {
                using (t) {
                    if (t.Id != tid) continue;
                    var s = t.ThreadState;
                    state[count] = (int)s;
                    reason[count] = s == System.Diagnostics.ThreadState.Wait ? (int)t.WaitReason : -1;
                    found = true;
                }
            }
            if (!found) return 2;
            end[count] = elapsed.ElapsedTicks;
            ++count;
            Thread.Sleep(jitter.Next(1, 14));
        }
        using (var w = new StreamWriter(args[2])) {
            w.WriteLine("pid,tid,initial_threads,tick_frequency,begin,end,state,wait_reason");
            for (int i=0;i<count;++i) w.WriteLine("{0},{1},{2},{3},{4},{5},{6},{7}", pid,tid,initialCount,Stopwatch.Frequency,begin[i],end[i],(System.Diagnostics.ThreadState)state[i],reason[i]<0?"":((ThreadWaitReason)reason[i]).ToString());
        }
        return count>=40?0:3;
    }
}
